(gen_random_uuid(), 'mount-laurel', 'local_legend', 'The town name came from the mount', 'Local history credits schoolteacher Hannah Gillingham with suggesting Mount Laurel''s name because of the laurel around the mount. Treat it as documented local naming lore.', 'Mount Laurel Historical Society', '🌿', null, '{"source": "https://www.mountlaurelhistoricalsociety.com/history"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.mountlaurelhistoricalsociety.com/history', 'cc0', 180, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'local_legend', 'Rancocas Woods was once a trolley-era playground', 'Local history records Masonville and Rancocas Woods as an amusement-park stop around a dammed lake in the 1920s. When you walk the shops, remember the older leisure landscape under it.', 'Mount Laurel Historical Society', '🎡', null, '{"source": "https://www.mountlaurelhistoricalsociety.com/history"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Rancocas Woods", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.mountlaurelhistoricalsociety.com/history', 'cc0', 181, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'first_timer_mistake', 'Assuming Paulsdale is always walk-in', 'Paulsdale has specific public hours, tour options, school-program days, and admission rules. Check the visit page before you arrive so the house story does not become a parking-lot story.', 'Alice Paul Center visit page', '⚠️', null, '{"source": "https://www.alicepaul.org/visit/"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Paulsdale", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.alicepaul.org/visit/', 'cc0', 190, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'first_timer_mistake', 'Showing up to the Woods on the wrong rhythm', 'Rancocas Woods feels different on quiet shop days, farmers market Sundays, and craft-show weekends. Check the calendar first, then choose the pace you actually want.', 'Rancocas Woods event schedule', '🗓️', null, '{"source": "https://rancocaswoodseventsnshops.com/farmers-market"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Rancocas Woods", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://rancocaswoodseventsnshops.com/farmers-market', 'cc0', 191, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'neighborhood_decode', 'Rancocas Woods is shops plus forest edge', 'Read the Woods as a village of small shops beside state-park land, not a sealed mall. The useful local move is to pair a market stop with time outdoors.', 'Rancocas Woods Business Association', '🧭', null, '{"source": "https://rancocaswoodseventsnshops.com/rw-business-association"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Rancocas Woods", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://rancocaswoodseventsnshops.com/rw-business-association', 'cc0', 200, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'neighborhood_decode', 'Paulsdale is a house and a movement', 'The site is Alice Paul''s birthplace, but the current center also teaches leadership, gender justice, and civic engagement. Read the place through both preservation and action.', 'Alice Paul Center mission', '🏛️', null, '{"source": "https://www.alicepaul.org/about-the-institute/"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Paulsdale", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.alicepaul.org/about-the-institute/', 'cc0', 201, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'photo_prompt', 'Frame the Paulsdale porch as a classroom', 'From public visitor space, photograph the porch and landscape as a leadership setting rather than just a pretty old house. Avoid faces from tours or programs unless you have consent.', 'Paulsdale visit context', '📷', null, '{"source": "https://www.alicepaul.org/visit/"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Paulsdale", "profile": "local-expert-addons", "prompt_type": "historic_site", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.alicepaul.org/visit/', 'cc0', 210, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'photo_prompt', 'Shoot the Woods at maker scale', 'In Rancocas Woods, look for hand-painted signs, wood textures, and shop thresholds from public walkways. Ask before close-ups of vendors, shoppers, or handmade goods.', 'Rancocas Woods shops guide', '📷', null, '{"source": "https://rancocaswoodseventsnshops.com/shops"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Rancocas Woods", "profile": "local-expert-addons", "prompt_type": "maker_detail", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://rancocaswoodseventsnshops.com/shops', 'cc0', 211, 'reference_only'),
(gen_random_uuid(), 'mount-laurel', 'seasonal', 'Women’s Equality Day belongs at Paulsdale', 'Late August is the Paulsdale moment: the center hosts Women’s Equality Day programming around the birthplace of Alice Paul. Check the current event page for parking and schedule details.', 'Alice Paul Center event listing', '📅', null, '{"source": "https://www.alicepaul.org/womens-equality-day-2026/"}'::jsonb, '{"accessed": "2026-08-02", "best_season": "Late August", "confidence": "documented", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.alicepaul.org/womens-equality-day-2026/', 'cc0', 220, 'reference_only'),
(gen_random_uuid(), 'rome', 'name_origin', 'The name points back to Romulus', 'Rome''s name is traditionally tied to Romulus, the legendary founder raised in the city''s origin story. Treat the etymology as civic myth with real staying power.', 'Traditional origin noted by Encyclopaedia Britannica', '🐺', null, '{"source": "https://www.britannica.com/place/Rome"}'::jsonb, '{"accessed": "2026-08-10", "confidence": "source-backed", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.britannica.com/place/Rome', 'cc0', 110, 'reference_only'),
