(gen_random_uuid(), 'rome', 'watch', 'Watch Rome through civic media', 'Roma Capitale''s official media channel is useful for how the city explains public places, ceremonies, and services to residents. Use it as context, not as a sightseeing shortcut.', 'Official city media channel', '📺', null, '{"source": "https://www.comune.roma.it/web/it/social-media-n.page", "youtube_url": "https://www.youtube.com/notizieromacapitale"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "official-source", "creator": "Roma Capitale", "duration": "Channel", "platform": "YouTube", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "external_link_only", "rights_review": "link_only_ok", "wave": "2026-08"}'::jsonb, 'https://www.comune.roma.it/web/it/social-media-n.page', 'cc0', 161, 'reference_only'),
(gen_random_uuid(), 'rome', 'screen', 'Roman Holiday made the city a co-star', 'Watch Roman Holiday for the Rome every visitor still imagines: scooters, fountains, stairways, and public squares treated like a romantic map.', 'Classic film context', '🎞️', null, '{"source": "https://www.turismoroma.it/en/page/rome-movie-set", "website": "https://www.turismoroma.it/en/page/rome-movie-set"}'::jsonb, '{"accessed": "2026-08-10", "confidence": "source-backed", "platform": "Film: Roman Holiday", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "external_reference_only", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/page/rome-movie-set', 'cc0', 165, 'reference_only'),
(gen_random_uuid(), 'rome', 'screen', 'La Dolce Vita explains the flashbulb Rome', 'Use La Dolce Vita as a field note for Via Veneto, celebrity drift, late nights, and the Rome that gave modern paparazzi culture its vocabulary.', 'Classic film context', '📸', null, '{"source": "https://www.turismoroma.it/en/page/rome-movie-set", "website": "https://www.turismoroma.it/en/page/rome-movie-set"}'::jsonb, '{"accessed": "2026-08-10", "confidence": "source-backed", "platform": "Film: La Dolce Vita", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "external_reference_only", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/page/rome-movie-set', 'cc0', 166, 'reference_only'),
