(gen_random_uuid(), 'rome', 'local_legend', 'The coin is a promise to return', 'At Trevi Fountain, the familiar coin toss is a city ritual attached to the promise of returning to Rome. Treat it as legend and custom, not as a guaranteed outcome.', 'Legend noted by Turismo Roma', '🪙', null, '{"source": "https://www.turismoroma.it/en/places/trevi-fountain"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "legend", "neighborhood": "Trevi", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/places/trevi-fountain', 'cc0', 180, 'reference_only'),
(gen_random_uuid(), 'rome', 'local_legend', 'The Mouth of Truth still tests the nervous', 'The Bocca della Verita is tied to the tale that it can bite a liar''s hand. Read it as a playful Roman legend with a long tourist afterlife, especially after Roman Holiday.', 'Legend noted by Turismo Roma itinerary', '🫲', null, '{"source": "https://www.turismoroma.it/en/node/31554"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "legend", "neighborhood": "Bocca della Verita", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/node/31554', 'cc0', 181, 'reference_only'),
(gen_random_uuid(), 'rome', 'first_timer_mistake', 'Treating Trevi like a free-for-all', 'Before you go, check the current Trevi access rules. Visitor flow, payment, crowd limits, and maintenance windows can change, and sitting, eating, or smoking at the basin is not the move.', 'Access guidance from Turismo Roma', '⚠️', null, '{"source": "https://www.turismoroma.it/en/places/trevi-fountain"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Trevi", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/places/trevi-fountain', 'cc0', 190, 'reference_only'),
(gen_random_uuid(), 'rome', 'first_timer_mistake', 'Calling Trastevere only nightlife', 'Trastevere is evening energy, yes, but also churches, fountains, residents, and old lanes. Arrive before dinner once, then return at night with a quieter sense of the neighborhood.', 'Neighborhood context from Turismo Roma', '🌙', null, '{"source": "https://www.turismoroma.it/en/node/31554"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Trastevere", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/node/31554', 'cc0', 191, 'reference_only'),
(gen_random_uuid(), 'rome', 'neighborhood_decode', 'Trevi is a three-street machine', 'Read Trevi by its name: the rione gathers movement around a historic confluence of streets and water. Duck into side lanes when the fountain crush feels too loud.', 'Rione context from Turismo Roma', '🧭', null, '{"source": "https://www.turismoroma.it/en/page/rione-ii-trevi"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Trevi", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/page/rione-ii-trevi', 'cc0', 200, 'reference_only'),
(gen_random_uuid(), 'rome', 'neighborhood_decode', 'Trastevere rewards slow wandering', 'Across the Tiber, read Trastevere through its piazzas, fountains, church fronts, and lived-in lanes before you judge it by one restaurant row.', 'Neighborhood context from Turismo Roma', '🏘️', null, '{"source": "https://www.turismoroma.it/en/node/31554"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Trastevere", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/node/31554', 'cc0', 201, 'reference_only'),
(gen_random_uuid(), 'rome', 'photo_prompt', 'Find the small fountain of lovers', 'At Trevi, look to the right of the main monument for the small rectangular basin tied to the lovers'' tradition. Photograph the detail, not other visitors'' faces.', 'Detail noted by Turismo Roma', '📷', null, '{"source": "https://www.turismoroma.it/en/places/trevi-fountain"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "neighborhood": "Trevi", "profile": "local-expert-addons", "prompt_type": "detail", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://www.turismoroma.it/en/places/trevi-fountain', 'cc0', 210, 'reference_only'),
